def sort_colors(nums):
    # nums[:low] are 0s, nums[low:i] are 1s, nums[i:high + 1] have not been looked at, nums[high + 1:] are 2s
    low, i, high = 0, 0, len(nums) - 1
    while i <= high:
        if nums[i] == 0:
            nums[low], nums[i] = nums[i], nums[low]
            low += 1
            i += 1
        elif nums[i] == 2:
            nums[i], nums[high] = nums[high], nums[i]
            high -= 1                          # the value swapped in from the right is still unchecked, so i stays
        else:
            i += 1
